cypress_script:
describe('Sortable Data Tables', () => {
  it('should display two sortable tables', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.get('h1').should('contain', 'Data Tables');
    cy.get('#table1').should('be.visible');
    cy.get('#table2').should('be.visible');
  });

  it('should not change the URL when clicking on a non-functional link', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.get('a').contains('edit').first().click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/tables');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Sortable Data Tables', () => {
  test('should display two sortable tables', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    await expect(page.locator('h1')).toHaveText('Data Tables');
    await expect(page.locator('#table1')).toBeVisible();
    await expect(page.locator('#table2')).toBeVisible();
  });

  test('should not change the URL when clicking on a non-functional link', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    await page.click('a:has-text(edit)');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/tables');
  });
});
